  const URL='https://www4.sii.cl/mapasui/services/data/mapasFacadeService/getPredioNacional';
  const meta=ns=>({namespace:'cl.sii.sdi.lob.bbrr.mapas.data.api.interfaces.MapasFacadeService/'+ns,
    conversationId:'UNAUTHENTICATED-CALL',transactionId:(crypto.randomUUID?crypto.randomUUID():Date.now()+''+Math.random())});
  const one=async(x)=>{
    const payload={metaData:meta('getPredioNacional'),
      data:{predio:{comuna:x.c,manzana:x.mz,predio:x.pr},
        servicios:[{comuna:x.c,layer:'sii:BR_CART_AH_MUESTRAS',style:'AH_MUESTRA_EAC_14_2022',eac:14,eacano:2022}]}};
    for(let i=0;i<2;i++){ try{
      const r=await fetch(URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
      const j=await r.json(); const d=j&&j.data; if(d) return d;
    }catch(e){} await new Promise(r=>setTimeout(r,300)); }
    return null;
  };
  const out=[]; let done=0, ok=0;
  for(let i=0;i<Q.length;i+=6){
    const batch=Q.slice(i,i+6);
    const rs=await Promise.all(batch.map(one));
    batch.forEach((x,k)=>{ const d=rs[k]||{}; const ah=d.datosAh||{};
      const vu=ah.valorUnitario||0; if(vu) ok++;
      out.push({id:x.id, rol:d.rol||(x.mz+'-'+x.pr), comuna:d.nombreComuna||'', destino:d.destinoDescripcion||'',
        ah:d.ah||'', valor_m2_clp:vu, rango_sup:(ah.rangoSuperficie||'').trim(),
        avaluo_total_clp:d.valorTotal||0, lat:d.ubicacionX||'', lon:d.ubicacionY||''}); });
    done+=batch.length; if(done%60===0||done>=Q.length) console.log(`SII ${done}/${Q.length} · con valor: ${ok}`);
    await new Promise(r=>setTimeout(r,120));
  }
  const cols=['id','rol','comuna','destino','ah','valor_m2_clp','rango_sup','avaluo_total_clp','lat','lon'];
  const esc=v=>`"${(v??'').toString().replace(/"/g,'""')}"`;
  const csv=[cols.join(';'),...out.map(r=>cols.map(c=>esc(r[c])).join(';'))].join('\n');
  const b=new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8;'}); const a=document.createElement('a');
  a.href=URL.createObjectURL?URL.createObjectURL(b):window.URL.createObjectURL(b);
  a.href=window.URL.createObjectURL(b); a.download='sii_valores_suelo.csv'; a.click();
  console.log('LISTO:', ok, 'con valor de suelo /', out.length, '. Sube el CSV al chat.');
